// poi-jungle — ONE layout for BANANA TEMPLE, RIPE PEAK and MIST FALLS, shared by the server (colliders) and the client
// (visuals). Pure math, no three.js. Terrain-dependent layouts (peak, falls) are RESOLVED against a height sampler
// `h(x, z)` into plain data ONCE by an offline bake (reads public/assets/terrain/island.bin — the bytes
// the client + server load) and stored in shared/pois/jungle-baked.json. Server colliders and client visuals are both
// built from that baked data (never from two different samplers). The bake's check fails when island.bin changed.
import type { Box } from "../world/colliders";
import { type InteriorRoom } from "./interior-kit";
import { poiById } from "../world/map";
import type { FallsResolved } from "./jungle-falls";
import * as dmath from "../sim/dmath";

export type H = (x: number, z: number) => number;
export type Clearing = { x: number; z: number; r: number } | { x: number; z: number; hx: number; hz: number; yaw?: number };

/** small deterministic PRNG (same as the client kit's) */
export function mulberry(seed: number) {
  let a = seed >>> 0 || 1;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const box = (x: number, y: number, z: number, w: number, h: number, d: number, yaw = 0, surf: Box["surf"] = "stone"): Box => ({ c: [x, y, z], h: [w / 2, h / 2, d / 2], yaw, surf });

// =====================================================================================================================
// BANANA TEMPLE — local frame: origin at the POI centre, y = 0 is the pad (world y 28). All numbers in metres.
// =====================================================================================================================
export const TEMPLE_C = (() => { const p = poiById("banana-temple"); return { x: p.x, z: p.z, y: p.padY as number }; })();
/** the temple's local frame is rotated 180° about Y so the façade (+z local) faces NORTH toward the atmos sun:
 *  world = (C.x − lx, C.y + ly, C.z − lz). Directions/yaws rotate by π. Client builds inside a Group with rotation.y = π. */
export const templeToWorld = (lx: number, lz: number): [number, number] => [TEMPLE_C.x - lx, TEMPLE_C.z - lz];
export interface Tier { half: number; y0: number; h: number }
export interface Tower { x: number; z: number; w: number; h: number; ruin: number }
/** an axis-aligned box in the temple LOCAL frame: [x0, y0, z0, x1, y1, z1] */
export type AABB = [number, number, number, number, number, number];
/** a straight stair: the bottom edge's centre at (x, y, z), steps rising along `dir`; each step solid down to `base`
 *  (null = a slab `slab` m thick — cantilevered / stacked flights you can walk under) */
export interface Stair { x: number; y: number; z: number; dir: "x+" | "x-" | "z+" | "z-"; width: number; steps: number; rise: number; tread: number; base: number | null; slab?: number }
