    for (const sx of [-1, 1]) for (const [inset, proud] of [[0, 0.35], [0.75, 0.62]]) { const d = proud * 0.5 + 0.25; A([sx * (r + 0.35 + inset) - 0.35, T.door.sill, P.z0, sx * (r + 0.35 + inset) + 0.35, T.door.sill + spring, P.z0 + d].map((v, i) => i === 0 || i === 3 ? v : v) as AABB); }
