  fills?: Slab[];
  rocks: PeakRock[];
  seams: Array<{ pts: Array<[number, number, number]>; w: number; fan?: boolean }>;
  crag: { x: number; z: number; ground: number; top: number; rTop: number; rBase: number; ledge: { x: number; z: number; y: number; r: number; ground: number }; tiers: Array<[number, number]>; /** per tier: 8 radius multipliers (lobes; 1 on the stair side) */ lobes: number[][]; flights: Flight[] };
  crate: [number, number, number, number];
  /** the approach TRAILS: grade-limited carved stone paths from the walkable outskirts up to the fan / rim network */
  trails?: TrailStep[][];
