  for (const b of R.benches) { if (b.a.length < 4) continue; for (const f of [0.22, 0.78]) { const j = Math.round(f * (b.a.length - 1)), [x, z] = pt(b.a[j], (b.rin[j] + b.rout[j]) / 2); floor.push([x, b.y, z]); } }
