    if (!((r.kind === 1 && !r.nc) || r.kind === 4)) continue;
    const k = r.kind === 4 ? 1 : 0.92, y = r.kind === 4 ? r.y + 0.1 : r.y, hy = r.kind === 4 ? r.sy + 0.1 : r.sy * k, a = simYaw(r.ry);
