    if (d < 0.01 || d > dmath.hypot(A.hx, A.hz) + dmath.hypot(B.hx, B.hz) + 2) continue;
    const ux = dx / d, uz = dz / d, ta = exit(A, ux, uz), tb = exit(B, -ux, -uz), gap = d - ta - tb;
