  const PL = RIM.plateau, nA = Math.round(Math.PI * 2 / PL.step), cr0: number[] = [], ch0: number[] = [];
  for (let i = 0; i < nA; i++) { const [cr, ch] = crest(i * PL.step); cr0.push(cr); ch0.push(ch); }
