  for (let pass = 0; pass < 200; pass++) { let worst = 0; for (let i = 0; i < nA; i++) { const j = (i + 1) % nA, d = ys[j] - ys[i]; worst = Math.max(worst, Math.abs(d)); if (d > 0.38) ys[i] = ys[j] - 0.38; else if (d < -0.38) ys[j] = ys[i] - 0.38; } if (worst <= 0.39) break; }
