  const rimAt = (a: number) => { const u = ((a % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2) / PL.step, i = Math.floor(u) % nA, j = (i + 1) % nA, t = u - Math.floor(u); return { y: rim.y[i] + (rim.y[j] - rim.y[i]) * t, cr: rim.cr[i] + (rim.cr[j] - rim.cr[i]) * t, i }; };

