    if (!b.a.length) continue;
    let aa = a; while (aa < b.a[0] - Math.PI) aa += Math.PI * 2; while (aa > b.a[0] + Math.PI) aa -= Math.PI * 2;
    if (aa < b.a[0] || aa > b.a[b.a.length - 1]) continue;
    let j = 0; while (j < b.a.length - 2 && b.a[j + 1] < aa) j++;
    const t = (aa - b.a[j]) / ((b.a[j + 1] - b.a[j]) || 1), ri = b.rin[j] + (b.rin[j + 1] - b.rin[j]) * t, ro = b.rout[j] + (b.rout[j + 1] - b.rout[j]) * t;
    if (r >= ri && r <= ro) best = Math.max(best, b.y);
